import{_ as o,c as i,o as t,ah as e}from"./chunks/framework.BkHe6ehV.js";const p=JSON.parse('{"title":"LongCat 系列","description":"","frontmatter":{"title":"LongCat 系列","date":"2025-12-06 11:53:36","create":"2025-12-06 11:53:36","categories":[],"tags":[],"readingStats":{"words":8689,"minutes":26,"images":5}},"headers":[],"relativePath":"posts/llm/industry/mainllm/10-longcat-series.md","filePath":"posts/llm/industry/mainllm/10-longcat-series.md","lastUpdated":1785944275000}'),s={name:"posts/llm/industry/mainllm/10-longcat-series.md"};function n(a,l,c,r,d,g){return t(),i("div",null,l[0]||(l[0]=[e('<h2 id="变化点" tabindex="-1">变化点 <a class="header-anchor" href="#变化点" aria-label="Permalink to &quot;变化点&quot;">​</a></h2><div class="custom-block tip"><div class="custom-block-title">2026</div><p><strong>2026.01 · <a href="#_2601-longcat-flash-thinking-2601-环境扩展、噪声-rl、heavy-thinking">LongCat-Flash-Thinking-2601</a></strong></p><ul><li>扩大可验证环境和 RL 任务，加入噪声课程增强鲁棒性。</li><li>在推理端增加 Heavy Thinking 并行探索，扩展高难任务能力。</li></ul></div><div class="custom-block info"><div class="custom-block-title">2025</div><p><strong>2025.09 · <a href="#_2509-longcat-flash-thinking-领域-rl、dora、参数融合">LongCat-Flash-Thinking</a></strong></p><ul><li>加入推理 MidTrain、领域 RL 与参数融合，再进行通用 RL。</li><li>DORA 支撑异步多轮交互训练。</li></ul><p><strong>2025.09 · <a href="#_2509-longcat-flash-零计算专家、scmoe、动态计算">LongCat-Flash</a></strong></p><ul><li>引入零计算专家，按 token 动态分配计算量。</li><li>ScMoE 重叠通信与计算，提高 MoE 推理效率。</li></ul></div><h2 id="_2601-longcat-flash-thinking-2601-环境扩展、噪声-rl、heavy-thinking" tabindex="-1">(2601) LongCat-Flash-Thinking-2601 (环境扩展、噪声 RL、Heavy Thinking) <a class="header-anchor" href="#_2601-longcat-flash-thinking-2601-环境扩展、噪声-rl、heavy-thinking" aria-label="Permalink to &quot;(2601) LongCat-Flash-Thinking-2601 (环境扩展、噪声 RL、Heavy Thinking)&quot;">​</a></h2><p><strong>🌺 论文摘要</strong></p><div class="custom-block danger"><div class="custom-block-title">LongCat-Flash-Thinking-2601 摘要</div><p><strong>参考链接</strong></p><ul><li><a href="https://www.alphaxiv.org/abs/2601.16725" target="_blank" rel="noreferrer">paper</a>，<a href="https://github.com/meituan-longcat/LongCat-Flash-Thinking-2601" target="_blank" rel="noreferrer">官方仓库</a>。</li></ul><p><strong>问题背景</strong></p><ul><li>Agent 长程交互数据稀缺；工具依赖、环境故障和用户表达差异限制跨场景泛化。</li><li>多环境耗时不均，容易出现异步训练等待、数据失衡和上下文溢出。</li></ul><p><strong>核心方法</strong></p><ul><li><strong>数据与环境</strong>：合成 Agent 轨迹做 MidTrain / 冷启动；工具依赖图扩展为 <code>20+领域、上万可执行环境</code>。</li><li><strong>多环境 RL</strong>：GSPO、难度课程、动态预算与过采样；逐步加入指令、工具噪声，训练异常恢复。</li><li><strong>系统与推理扩展</strong>：DORA 支持异步交互；Heavy Thinking 并行探索后汇总，并对汇总阶段单独 RL。</li></ul><p><strong>模型效果(560B-A27B，领域 RL + 融合)</strong></p><ul><li>BrowseComp <code>56.6 → 73.1</code>，对应无/有上下文管理；τ₂ Avg <code>88.2</code>，VitaBench <code>29.3</code>。</li><li>IMO-AnswerBench 普通/Heavy <code>78.6 / 86.8</code>；SWE-bench Verified <code>70.0</code>，R2E-Gym、Avg@5。</li></ul><p><strong>重要结论</strong></p><ul><li>噪声训练使 VitaBench-Noise <code>13.3 → 20.5</code>，同时保持正常任务表现，鲁棒性可直接训练。</li><li>扩环境必须同时维护工具依赖和状态一致性，否则正确行为也可能得到错误负奖励。</li></ul><p><strong>核心贡献</strong></p><ul><li>可验证环境扩展、异步多环境 RL、噪声训练和 Heavy Thinking 的完整训练方案。</li></ul><p><strong>未来方向</strong></p><ul><li>改进异步样本时效管理，开放噪声与随机任务评测，进一步平衡长任务能力和计算成本。</li></ul></div><h3 id="问题背景" tabindex="-1">问题背景 <a class="header-anchor" href="#问题背景" aria-label="Permalink to &quot;问题背景&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">长程 Agent 的训练瓶颈</div><p><strong>数据与环境</strong></p><ul><li>常规文本缺少主动工具调用、规划和状态跟踪，直接 RL 容易消耗大量无效探索。</li><li>随机增加工具会破坏依赖和数据库状态，使可解任务变为不可解任务。</li></ul><p><strong>训练与部署</strong></p><ul><li>搜索、代码和多工具任务耗时差异大，同步 batch 被最慢样本拖住。</li><li>真实用户表达含糊、工具会失败；只在理想环境训练的策略缺少恢复能力。</li></ul></div><h3 id="核心方法" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法" aria-label="Permalink to &quot;核心方法&quot;">​</a></h3><h4 id="数据与环境构建" tabindex="-1">数据与环境构建 <a class="header-anchor" href="#数据与环境构建" aria-label="Permalink to &quot;数据与环境构建&quot;">​</a></h4><div class="custom-block note"><div class="custom-block-title">混合轨迹合成</div><p><strong>文本流程重构</strong></p><ul><li>从教程、说明和多步流程提取工具 schema，转成多轮用户—Agent 交互。</li><li><strong>工具拆解</strong>：把部分参数藏到环境中，要求模型先查询，再执行原操作。</li><li><strong>决策扩展</strong>：在关键动作处生成候选，让模型比较后选择，显式监督规划与决策。</li></ul><p><strong>环境驱动合成</strong></p><ul><li>实现轻量 Python 工具环境，以参数依赖建立有向图，采样有效执行链。</li><li>由执行链反向生成用户需求与模拟器提示，执行代码并检查数据库最终状态。</li><li>将复杂目标拆解与正确首步配对，补充粗到细的规划监督。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">冷启动数据筛选</div><p><strong>通用推理</strong></p><ul><li>用 K-Center-Greedy 保持样本覆盖，再以滑动窗口 PPL 强调局部难点。</li><li>每条样本取 <code>512-token窗口</code>的最大平均 PPL，避免长序列平均掩盖关键困难位置。</li><li>从大语料中选取 <code>210K</code> 通用思考样本。</li></ul><p><strong>Agent 轨迹</strong></p><ul><li>Coding：要求任务修复且无回归，过滤无效动作；压缩早期步骤，保留长程调试。</li><li>Search：检查问题全部约束，排除凭局部证据碰巧猜对的轨迹。</li><li>Tool-use：覆盖 <code>33类领域</code>冷启动数据；验证最终状态，Mask 失败调用和格式错误的 loss。</li><li>保留完整历史让模型理解失败语境，但不把错误动作当作正确监督。</li></ul></div><div class="custom-block important"><div class="custom-block-title">工具依赖图与环境扩展</div><p><strong>领域到可执行工具</strong></p><ul><li>领域定义 → 工具集 → 统一数据库 schema → 工具代码与状态实现。</li><li>用单元测试和 Debug Agent 修复，随后构建工具依赖图；每领域包含 <code>60+工具</code>。</li></ul><p><strong>任务与状态初始化</strong></p><ul><li>先采样一条有效工具链，依次创建它所需的数据库对象与前置状态。</li><li>基于完整工具链生成任务、用户画像和 rubric，并检查可接受的正确解及错误解。</li></ul><p><strong>保持可解性的扩展</strong></p><ul><li>从种子链做 BFS，只有依赖已满足的新工具才加入环境。</li><li>根据图复杂度、剩余工具和替代路径难度，决定是否加入更多种子链。</li><li>最终每环境至少 <code>20个工具</code>；增加选择难度的同时，保留可执行正确路径。</li></ul></div><figure style="margin:24px 0;"><img src="https://arxiv.org/html/2601.16725v2/domain_graph.png" alt="可执行环境的构建流程：从领域定义生成工具与数据库，再验证工具依赖关系，为任务扩展提供可运行的基础。" loading="lazy" style="display:block;margin:12px auto;background:#fff;" width="100%"><figcaption style="font-size:0.9em;line-height:1.6;color:var(--vp-c-text-2);"><strong>原文图 3：</strong>可执行环境的构建流程：从领域定义生成工具与数据库，再验证工具依赖关系，为任务扩展提供可运行的基础。 <a href="https://arxiv.org/html/2601.16725v2#S3.F3" target="_blank" rel="noreferrer">来源</a></figcaption></figure><div class="custom-block note"><div class="custom-block-title">搜索任务合成</div><p><strong>多跳关系</strong></p><ul><li>从 Wikipedia 长尾实体扩展关系图，采样连通子图生成 QA。</li><li>模糊实体、地点、时间等直接线索，要求模型搜索关系链；验证答案与条件一致。</li></ul><p><strong>多条件歧义</strong></p><ul><li>Entity Agent 提取实体属性，Question Agent 抽取部分属性出题。</li><li>Verification Agent 搜索核对全部约束，Answer Agent 尝试找其他满足条件的答案。</li><li>若发现多解，追加属性重写问题，直到答案唯一；用解题成功率划分难度。</li></ul></div><h4 id="rl-算法与训练策略" tabindex="-1">RL 算法与训练策略 <a class="header-anchor" href="#rl-算法与训练策略" aria-label="Permalink to &quot;RL 算法与训练策略&quot;">​</a></h4><div class="custom-block tip"><div class="custom-block-title">课程、动态预算与 Self-Verification</div><p><strong>训练目标与课程</strong></p><ul><li>使用 GSPO 的序列级重要性比率和组内优势，主要依赖结果监督，并放宽长轨迹惩罚。</li><li>课程同时考虑成功率和能力依赖：基础工具调用 → 多步规划 → 组合约束决策。</li></ul><p><strong>预算分配</strong></p><ul><li>根据当前成功率等训练状态估计任务价值，用堆式贪心分配 rollout 预算。</li><li>多环境异步训练中，用历史成功率决定过采样次数，各重复组独立计算优势。</li><li>对低吞吐、较难领域增加配额，避免快速领域占满 batch 或等待慢领域形成空转。</li></ul><p><strong>Self-Verification</strong></p><ul><li>生成训练停滞时，启动辅助验证阶段，让模型判断自己的 on-policy 轨迹。</li><li>聚焦困难样本，并把验证信号与对应生成质量关联，促进生成而非只提高判题分数。</li></ul></div><div class="custom-block note"><div class="custom-block-title">混合上下文管理</div><p><strong>压缩</strong></p><ul><li>上下文超过 <code>80K</code> 时，由模型总结历史工具结果，保留关键证据后继续。</li><li>冷启动加入 <code>15K</code> 高质量摘要样本，使压缩后的证据仍能支持后续决策。</li></ul><p><strong>重置</strong></p><ul><li>达到最大交互轮次时，清空历史，从原问题与系统提示重新开始。</li><li>训练中逐渐提高丢弃阈值，让困难任务获得更多推理步骤。</li><li>摘要维持已有探索，重置提供新的搜索机会，两者按不同触发条件组合。</li></ul></div><div class="custom-block important"><div class="custom-block-title">Robust RL：噪声课程</div><p><strong>噪声类型</strong></p><ul><li><strong>Instruction Noise</strong>：用户表达含糊、交互习惯变化，需要澄清和约束确认。</li><li><strong>Tool Noise</strong>：执行失败、返回不一致、部分信息缺失，需要重试、诊断与恢复。</li></ul><p><strong>课程控制</strong></p><ul><li>从轻微扰动开始，根据当前鲁棒性逐步增加噪声难度与种类。</li><li>始终保留任务可解性，避免将环境被破坏造成的失败作为模型负反馈。</li><li>用同一任务在正常/噪声环境的差距衡量鲁棒性，而非只看训练奖励。</li></ul></div><h4 id="训练系统与推理扩展" tabindex="-1">训练系统与推理扩展 <a class="header-anchor" href="#训练系统与推理扩展" aria-label="Permalink to &quot;训练系统与推理扩展&quot;">​</a></h4><div class="custom-block note"><div class="custom-block-title">流式执行与领域调度</div><p><strong>流水线</strong></p><ul><li>RolloutManager 管采样，SampleQueue 管样本时效，Trainer 管经验处理与更新。</li><li>生成、环境执行、奖励计算按单样本流式推进，完成即入队，不等待整批结束。</li><li>多版本 rollout 与训练并行；较旧版本限制新增请求，控制样本滞后。</li></ul><p><strong>环境扩展</strong></p><ul><li>轻量全局 Manager 管元数据，多个 Controller 分别管理虚拟 rollout 组。</li><li>基于 CPU 空闲状态放置环境，支持约 <code>400台机器 / 32K并发环境</code>。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">Prefill-Decode 分离与 KV Cache Swap</div><p><strong>PD 分离</strong></p><ul><li>长输入的 prefill 与持续 decode 放在不同设备组，避免新请求打断生成图执行。</li><li>KV Cache 分块异步传输，和后续块计算重叠。</li></ul><p><strong>CPU Cache</strong></p><ul><li>设备显存紧张时将 KV Cache 换到 CPU，再按需恢复，避免反复重算长历史。</li><li>结合请求并发控制，减少长尾 rollout 对设备利用率的影响。</li></ul></div><div class="custom-block important"><div class="custom-block-title">Heavy Thinking：并行探索与汇总 RL</div><p><strong>两阶段推理</strong></p><ul><li>Thinking Model 并行生成多个候选，扩大探索宽度。</li><li>Summary Model 比较候选、反思并整合答案；并非仅按答案多数投票。</li><li>多轮场景保留共享对话历史，各轮候选只保留回答内容，再由汇总模型给出统一回复。</li></ul><p><strong>训练与模型</strong></p><ul><li>汇总阶段额外进行 RL，提高筛选、纠错和整合能力。</li><li>Thinking 与 Summary 可共享参数，也可使用不同模型；Heavy 需要额外推理预算。</li></ul></div><figure style="margin:24px 0;"><img src="https://arxiv.org/html/2601.16725v2/heavy_mode.png" alt="Heavy Thinking：并行轨迹提供不同探索结果，再由汇总阶段形成答案；重点看探索与综合两个环节如何连接。" loading="lazy" style="display:block;margin:12px auto;background:#fff;" width="100%"><figcaption style="font-size:0.9em;line-height:1.6;color:var(--vp-c-text-2);"><strong>原文图 10：</strong>Heavy Thinking：并行轨迹提供不同探索结果，再由汇总阶段形成答案；重点看探索与综合两个环节如何连接。 <a href="https://arxiv.org/html/2601.16725v2#S4.F10" target="_blank" rel="noreferrer">来源</a></figcaption></figure><div class="custom-block note"><div class="custom-block-title">ZigZag：独立长上下文变体</div><p><strong>结构转换</strong></p><ul><li>校准 attention 层重要性，将约一半层换成 SSA，其余保留完整 MLA。</li><li>SSA 每层只看 <code>1个 sink块 + 7个局部块</code>，每块 <code>128 tokens</code>，共 <code>1024 tokens</code>。</li><li>完整层与局部层交替传播信息，保留跨远距离关联。</li></ul><p><strong>继续训练</strong></p><ul><li>替换后继续长上下文 MidTrain，并用 YaRN 扩至 <code>1M</code>。</li><li>这是额外发布的 ZigZag 模型；主模型表中的全部结果并非在该结构下取得。</li></ul></div><h3 id="实验设置-longcat-flash-thinking-2601" tabindex="-1">实验设置(LongCat-Flash-Thinking-2601) <a class="header-anchor" href="#实验设置-longcat-flash-thinking-2601" aria-label="Permalink to &quot;实验设置(LongCat-Flash-Thinking-2601)&quot;">​</a></h3><div class="custom-block tip"><div class="custom-block-title">模型与训练</div><p><strong>模型与阶段</strong></p><ul><li><code>560B</code> MoE，平均激活 <code>27B</code>；继承 Flash-Chat 的基础结构与预训练分布。</li><li>MidTrain：<code>500B tokens / 32K→128K</code>，另 <code>40B / 256K</code>；冷启动后分领域 RL，再融合。</li><li>Tool-use 领域内部联合多环境训练；DORA 支持异步 GSPO 与领域过采样。</li></ul><p><strong>推理协议</strong></p><ul><li>默认 <code>temperature=1.0, top_p=1.0, top_k=-1</code>。</li><li>数学以代码工具辅助推理为主：IMO-AnswerBench <code>Avg@4</code>，其他数学任务 <code>Avg@16</code>。</li><li>SWE-bench Verified：R2E-Gym、<code>Avg@5</code>；LCB 使用 <code>2024.08～2025.05</code> 的 <code>454题 / Avg@4</code>。</li></ul><p><strong>Agent 评测</strong></p><ul><li>BrowseComp 分别测试有/无上下文管理；RWSearch <code>200题</code>，各模型统一无上下文管理。</li><li>τ₂ 使用 GPT-4.1 用户模拟器并修复 airline 问题；Vita 使用更新后的 verifier。</li><li>Noise 测试在同一任务注入扰动；随机复杂任务每次 <code>100题、4+领域</code>，重复三次统计。</li></ul></div><h3 id="关键结果-longcat-flash-thinking-2601-领域-rl-融合" tabindex="-1">关键结果(LongCat-Flash-Thinking-2601，领域 RL + 融合) <a class="header-anchor" href="#关键结果-longcat-flash-thinking-2601-领域-rl-融合" aria-label="Permalink to &quot;关键结果(LongCat-Flash-Thinking-2601，领域 RL + 融合)&quot;">​</a></h3><div class="custom-block important"><div class="custom-block-title">环境与鲁棒性消融</div><p><strong>噪声训练直接有效</strong></p><ul><li>VitaBench-Noise：无噪声训练 <code>13.3</code> → 有噪声训练 <code>20.5</code>；正常 VitaBench <code>28.6 → 29.3</code>。</li><li>τ₂-Noise：<code>62.2 → 67.1</code>；正常 τ₂ <code>87.1 → 88.2</code>。</li><li>噪声收益主要体现在异常环境，正常表现也保持稳定，支持将恢复能力纳入训练目标。</li></ul><p><strong>跨环境泛化</strong></p><ul><li>随机复杂任务 <code>35.8</code>，报告对照最高；VitaBench <code>29.3</code>，仍低于 Gemini 3 Pro <code>31.5</code>。</li><li>噪声 Vita <code>20.5</code> 仍低于正常 <code>29.3</code>，扰动造成的能力下降尚未消除。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">搜索、推理与代码</div><p><strong>上下文管理</strong></p><ul><li>BrowseComp <code>56.6 → 73.1</code>，对应无/有上下文管理；混合压缩与重置有利于扩大搜索预算。</li><li>摘要阈值消融中 <code>80K</code> 优于 <code>20K</code> 和 <code>100K</code>，过早压缩和过晚压缩都可能损失效率。</li><li>RWSearch <code>79.5</code>，低于 GPT-5.2 <code>82.0</code>，在真实复杂搜索中接近其表现。</li></ul><p><strong>Heavy Thinking</strong></p><ul><li>IMO-AnswerBench <code>78.6 → 86.8</code>；HMMT-25 <code>93.4 → 97.5</code>。</li><li>工具辅助 AIME-25 <code>99.6 → 100.0</code>；GPQA <code>80.5 → 85.2</code>，汇总推理在困难题上更有价值。</li></ul><p><strong>代码与系统</strong></p><ul><li>SWE-bench Verified <code>70.0</code>，低于表中 DeepSeek-V3.2 <code>73.1</code>；LCB <code>82.8</code>，保持较强算法代码能力。</li><li>DORA 在不同生产任务中约为同步训练的 <code>2～4倍</code>速度。</li><li>独立 ZigZag 变体最高约 <code>1.5倍</code>推理加速，并支持 <code>1M</code> 长上下文。</li></ul></div><h3 id="未来方向" tabindex="-1">未来方向 <a class="header-anchor" href="#未来方向" aria-label="Permalink to &quot;未来方向&quot;">​</a></h3><div class="custom-block info"><div class="custom-block-title">后续研究</div><p><strong>作者计划</strong></p><ul><li>探索更宽松的时效控制与 staleness-aware 稳定化，提高异步训练利用率。</li><li>开放噪声注入流程，将随机复杂任务整合进评测平台。</li></ul><p><strong>笔记归纳</strong></p><ul><li>扩展具有真实状态变化的环境，同时持续检查任务可解性和 verifier 一致性。</li><li>联合优化 Heavy 并行宽度、汇总成本与上下文管理，减少重复探索。</li><li>分析噪声类型与失败阶段，针对仍有明显性能下降的工具恢复和长程规划继续训练。</li></ul></div><h2 id="_2509-longcat-flash-thinking-领域-rl、dora、参数融合" tabindex="-1">(2509) LongCat-Flash-Thinking (领域 RL、DORA、参数融合) <a class="header-anchor" href="#_2509-longcat-flash-thinking-领域-rl、dora、参数融合" aria-label="Permalink to &quot;(2509) LongCat-Flash-Thinking (领域 RL、DORA、参数融合)&quot;">​</a></h2><p><strong>🌺 论文摘要</strong></p><div class="custom-block danger"><div class="custom-block-title">LongCat-Flash-Thinking 摘要</div><p><strong>参考链接</strong></p><ul><li><a href="https://www.alphaxiv.org/abs/2509.18883" target="_blank" rel="noreferrer">paper</a>，<a href="https://github.com/meituan-longcat/LongCat-Flash-Thinking" target="_blank" rel="noreferrer">官方仓库</a>。</li></ul><p><strong>问题背景</strong></p><ul><li>通用预训练缺少多样的长 CoT；混合领域 RL 中，输出长度和难度差异造成异步数据失衡。</li><li>长尾 rollout、旧策略样本和推理/训练引擎差异，共同影响大规模 RL 的效率与稳定性。</li></ul><p><strong>核心方法</strong></p><ul><li><strong>数据与冷启动</strong>：推理增强 MidTrain + 通用、Lean4、工具推理 SFT；比较有无工具收益筛选任务。</li><li><strong>领域 RL</strong>：STEM、Code、Agentic 独立训练专家，参数融合后再做通用 PPO。</li><li><strong>异步训练系统</strong>：DORA 按策略版本流式采样；结合概率修正、样本时效与异常 Mask，稳定多版本训练。</li></ul><p><strong>模型效果(560B-A27B，领域 RL + 融合 + 通用 PPO)</strong></p><ul><li>AIME-25 <code>90.6</code>，LCB <code>79.4</code>；MiniF2F-Test <code>Pass@1=67.6</code>。</li><li>AIME-25 使用工具后，输出 <code>19653 → 6965 tokens</code>，准确率 <code>90.6 → 90.0</code>。</li></ul><p><strong>重要结论</strong></p><ul><li>工具可承担部分计算，显著缩短模型输出；更长 CoT 并非唯一的推理扩展路线。</li><li>专家融合在多个领域保留或略超专家表现，支持将训练日程差异与最终单模型部署分开处理。</li></ul><p><strong>核心贡献</strong></p><ul><li>领域并行 RL 与参数融合路线，以及保持采样版本一致的异步训练系统 DORA。</li></ul><p><strong>未来方向</strong></p><ul><li><strong>笔记归纳</strong>：优化跨领域能力融合、旧样本利用率与训练稳定性的取舍，增强真实 Agent 任务。</li></ul></div><h3 id="问题背景-1" tabindex="-1">问题背景 <a class="header-anchor" href="#问题背景-1" aria-label="Permalink to &quot;问题背景&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">推理数据与异步训练</div><p><strong>推理模式不足</strong></p><ul><li>通用语料中 STEM、代码比例有限，显式长 CoT 更稀缺，后训练容易形成单一解题模式。</li></ul><p><strong>领域与系统差异</strong></p><ul><li>STEM、Code、Agent 的输出长度分布不同，异步混训会使不同 batch 的领域比例明显波动。</li><li>等待最长回答会降低利用率；强行切换未完成回答的模型版本又需要重新 prefill。</li></ul></div><h3 id="核心方法-1" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法-1" aria-label="Permalink to &quot;核心方法&quot;">​</a></h3><h4 id="训练数据与冷启动" tabindex="-1">训练数据与冷启动 <a class="header-anchor" href="#训练数据与冷启动" aria-label="Permalink to &quot;训练数据与冷启动&quot;">​</a></h4><div class="custom-block note"><div class="custom-block-title">推理增强 MidTrain</div><p><strong>推理语料</strong></p><ul><li>加入数学、物理、化学与算法编程问题，优先多步逻辑推理而非简单事实问答。</li><li>规则与 LLM Judge 联合清洗、去重和去污染，混合原有通用语料，保留基础知识能力。</li></ul><p><strong>能力检查</strong></p><ul><li>先在相同结构的小 MoE 上比较 <code>pass@1～pass@128</code>，再将有效配方用于主模型。</li><li>同时关注一次回答与多次探索能否成功，避免仅优化输出格式而不扩展解题范围。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">通用推理与 Lean4 证明</div><p><strong>问题筛选</strong></p><ul><li>排除题目不完整、答案不一致和过易样本；代码题要求至少 <code>5个测试</code>和可执行评测脚本。</li><li>用专家成功率确定难度分布，再进行 rejection sampling，保留高质量 CoT。</li></ul></div><div class="custom-block note"><div class="custom-block-title">Formal Reasoning</div><p><strong>语句形式化</strong></p><ul><li><code>8B Autoformalizer</code> 将自然语言题目与答案转为 Lean4 statement。</li><li>编译检查语法，再由模型核对原题含义，避免形式上合法但题意被改变。</li></ul><p><strong>Expert Iteration</strong></p><ul><li>先用现有 prover 获得可验证证明，再补充自然语言推理，组成 <code>statement + thinking + proof</code>。</li><li>当前 prover 尝试未解决问题，Lean4 验证成功后加入数据集。</li><li>聚合新旧数据重新训练 prover，迭代扩充可解题范围。</li></ul></div><div class="custom-block important"><div class="custom-block-title">工具必要性筛选</div><p><strong>有/无工具对照</strong></p><ul><li>同一问题分别生成有工具、无工具轨迹，比较两组成功率。</li><li>保留无工具较难、有工具可解、两者差距足够大的任务，避免“看似调用工具，实际不需要”。</li></ul><p><strong>轨迹合成</strong></p><ul><li>连接真实 API、MCP 和模拟工具，生成候选交互轨迹。</li><li>Judge 检查答案、逻辑一致性与工具使用完整性，保留合格轨迹。</li><li>按调用次数、顺序/并行依赖和规划深度分层，供后续课程训练。</li></ul></div><h4 id="领域-rl-与能力融合" tabindex="-1">领域 RL 与能力融合 <a class="header-anchor" href="#领域-rl-与能力融合" aria-label="Permalink to &quot;领域 RL 与能力融合&quot;">​</a></h4><div class="custom-block note"><div class="custom-block-title">奖励系统</div><p><strong>可验证任务</strong></p><ul><li>STEM：Reasoning GenRM 比较问题、参考答案与模型答案，识别等价表达和复杂符号结果。</li><li>Code：sandbox 执行测试，支持 <code>20+语言</code>，一次编译供多个测试复用。</li></ul><p><strong>开放任务</strong></p><ul><li>从 SFT 模型训练判别式 RM，偏好数据由人工和模型共同标注。</li><li>长 CoT 任务只评价最终回答，避免把推理文本风格当作最终质量。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">Domain-Parallel RL</div><p><strong>训练数据</strong></p><ul><li>STEM 去掉不适合当前验证方式的多问、选择、判断题；Code 统一输入输出测试格式。</li><li>以 SFT 模型多次采样，保留有对有错的问题；Code 进一步排除歧义题与错误测试。</li></ul><p><strong>独立训练日程</strong></p><ul><li><strong>STEM</strong>：固定 <code>64K</code>，逐渐提高难度，动态调整正优势裁剪上界。</li><li><strong>Code</strong>：<code>48K → 56K → 64K</code>，输出长度 90 分位接近上限时扩展。</li><li><strong>Agentic</strong>：固定 <code>48K</code>，使用规范 think/tool-call 标签和调用格式奖励。</li></ul></div><div class="custom-block important"><div class="custom-block-title">参数融合与 General PPO</div><p><strong>Task Vector 融合</strong></p><ul><li>计算每个专家相对同一 SFT 的参数增量 <code>Δθᵢ=θRLᵢ−θSFT</code>。</li><li><strong>Normalization</strong>：对齐增量幅度，避免某个领域因更新量大占主导。</li><li><strong>Dropout</strong>：删除冗余增量；<strong>Erase</strong>：去掉方向冲突中的少数方向，缓解参数干扰。</li></ul><p><strong>通用对齐</strong></p><ul><li>融合后整理开放与合成任务，聚类去重、筛选困难高质量问题。</li><li>最后进行通用 PPO，恢复写作、指令遵循和安全等基础行为。</li></ul></div><figure style="margin:24px 0;"><img src="https://arxiv.org/html/2509.18883v2/parallel_training_pipeline.png" alt="整体训练路线：MidTrain/SFT 冷启动后并行训练领域专家，再融合并做通用 RL；重点看领域专长如何回到统一模型。" loading="lazy" style="display:block;margin:12px auto;background:#fff;" width="100%"><figcaption style="font-size:0.9em;line-height:1.6;color:var(--vp-c-text-2);"><strong>原文图 2：</strong>整体训练路线：MidTrain/SFT 冷启动后并行训练领域专家，再融合并做通用 RL；重点看领域专长如何回到统一模型。 <a href="https://arxiv.org/html/2509.18883v2#S1.F2" target="_blank" rel="noreferrer">来源</a></figcaption></figure><h4 id="异步-rl-系统" tabindex="-1">异步 RL 系统 <a class="header-anchor" href="#异步-rl-系统" aria-label="Permalink to &quot;异步 RL 系统&quot;">​</a></h4><div class="custom-block note"><div class="custom-block-title">流式采样与弹性角色</div><p><strong>两个设备组</strong></p><ul><li><strong>Standalone Group</strong>：主要执行 rollout；<strong>Elastic Group</strong>：在采样、经验计算、训练间切换。</li><li>样本完成即进入下一阶段，不等待最长回答；空闲训练设备可临时加入生成。</li></ul><p><strong>同回答保持同版本</strong></p><ul><li>保留多个旧策略，未完成回答继续使用自己的采样版本，复用或迁移已有 KV Cache。</li><li>负载均衡同时迁移权重和 Cache；过旧版本退出，相关样本按时效规则处理。</li><li>更新后逐层同步权重，开始新版本采样。</li></ul><p><strong>大规模优化</strong></p><ul><li>Streaming RPC 支持大量交互，图编译减少 kernel 调度开销。</li><li>高度 Expert Parallel 配合通信计算重叠，提高大 MoE 的 rollout 吞吐。</li></ul></div><figure style="margin:24px 0;"><img src="https://arxiv.org/html/2509.18883v2/streaming_framework.svg" alt="DORA 的流式调度：已完成轨迹及时进入训练，未完成轨迹可继续生成；图中同时展示策略版本限制与过期轨迹重采。" loading="lazy" style="display:block;margin:12px auto;background:#fff;" width="100%"><figcaption style="font-size:0.9em;line-height:1.6;color:var(--vp-c-text-2);"><strong>原文图 5：</strong>DORA 的流式调度：已完成轨迹及时进入训练，未完成轨迹可继续生成；图中同时展示策略版本限制与过期轨迹重采。 <a href="https://arxiv.org/html/2509.18883v2#S3.F5" target="_blank" rel="noreferrer">来源</a></figcaption></figure><div class="custom-block important"><div class="custom-block-title">异步 GRPO 与训推修正</div><p><strong>策略版本差异</strong></p><ul><li>当前策略与产生样本的旧策略不同，需要重要性比率与裁剪限制更新。</li><li>去掉 GRPO 的 KL 项；按 token 聚合，用全局最大生成长度归一化，缓解长度偏置。</li><li>三重裁剪分别控制负优势的大幅更新和正优势的探索上界。</li></ul><p><strong>引擎数值差异</strong></p><ul><li>同一权重在推理与训练引擎中的 logprob 可能不同，不能全归因于策略更新。</li><li>以训练引擎重算旧策略 logprob，再用截断重要性权重修正与采样引擎的差异。</li><li>前者约束“模型改了多少”，后者校正“同一模型的两套执行结果差多少”。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">在线筛选与异常反馈处理</div><p><strong>有效组与时效</strong></p><ul><li>过滤组内全对、全错任务，保留存在学习信号的样本组。</li><li>在线有放回采样；额外生成的数据进入 replay buffer，按比例与新样本混合并打散。</li><li>超过最大 staleness 的样本重新生成，控制旧数据复用带来的偏差。</li></ul><p><strong>Incomplete-Signal Masking</strong></p><ul><li>Sandbox 评分错误的样本屏蔽，避免系统故障被当作模型失败。</li><li>非重复行为但因长度上限截断的样本也屏蔽，避免把未完成输出直接当作负例。</li></ul></div><h3 id="实验设置-longcat-flash-thinking" tabindex="-1">实验设置(LongCat-Flash-Thinking) <a class="header-anchor" href="#实验设置-longcat-flash-thinking" aria-label="Permalink to &quot;实验设置(LongCat-Flash-Thinking)&quot;">​</a></h3><div class="custom-block tip"><div class="custom-block-title">模型、训练与评测</div><p><strong>模型与训练</strong></p><ul><li>从 LongCat-Flash-Base 开始，<code>560B</code> 总参数、平均激活 <code>27B</code>。</li><li>SFT：<code>context=48K, AdamW, lr=3e-5, 2 epochs</code>；RL 计算投入接近预训练的 <code>20%</code>。</li><li>STEM、Code、Agentic 分别 RL，随后参数融合与通用 PPO。</li></ul><p><strong>评测协议</strong></p><ul><li><code>temperature=1.0, top_p=0.95, top_k=-1</code>。</li><li>AIME、HMMT <code>Mean@32</code>；GPQA <code>Mean@16</code>；LCB <code>2024.08～2025.05 / Mean@4</code>。</li><li>MiniF2F-Test <code>244题</code>，Lean4 验证，统计 <code>Pass@1 / 8 / 32</code>。</li><li>工具任务覆盖 SWE-bench、BFCL、τ₂、VitaBench；另评知识、指令与安全。</li></ul><p><strong>对照设计</strong></p><ul><li>小规模 MidTrain 消融比较推理数据比例；奖励模型比较规则、无推理 GenRM 与有推理 GenRM。</li><li>分别检查领域专家与融合模型，以及同一模型有/无工具时的正确率和输出长度。</li></ul></div><h3 id="关键结果-longcat-flash-thinking-领域-rl-参数融合-ppo" tabindex="-1">关键结果(LongCat-Flash-Thinking，领域 RL + 参数融合 + PPO) <a class="header-anchor" href="#关键结果-longcat-flash-thinking-领域-rl-参数融合-ppo" aria-label="Permalink to &quot;关键结果(LongCat-Flash-Thinking，领域 RL + 参数融合 + PPO)&quot;">​</a></h3><div class="custom-block important"><div class="custom-block-title">训练机制的效果</div><p><strong>推理数据与奖励</strong></p><ul><li>小 MoE 的推理增强 MidTrain 在 <code>pass@1～pass@128</code> 均改善，说明收益包含多次探索的可解题范围。</li><li>人工标注测试集上，规则 RM <code>80.9%</code>、无推理 GenRM <code>94.0%</code>、Reasoning GenRM <code>98.8%</code>。</li><li>复杂表达需要语义验证，单纯字符串规则容易把正确答案判错。</li></ul><p><strong>专家融合</strong></p><ul><li>AIME-24 专家/融合 <code>93.6 / 94.3</code>；LCB <code>78.0 / 80.1</code>；τ₂ Avg <code>70.3 / 70.6</code>。</li><li>融合阶段在多个领域保留专家能力，缓解分别训练与单模型部署之间的冲突。</li></ul><p><strong>工具使用效率</strong></p><ul><li>AIME-25 输出 <code>19653 → 6965 tokens</code>，减少约 <code>64.5%</code>；准确率 <code>90.6 → 90.0</code>。</li><li>将适合执行的计算交给工具，可节省模型输出；完整延迟还需计算工具执行时间。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">最终模型表现</div><p><strong>推理与形式证明</strong></p><ul><li>AIME-25 <code>90.6</code>、HMMT-25 <code>83.7</code>；LCB <code>79.4</code>，接近 GPT-5 <code>80.6</code>。</li><li>MiniF2F-Test <code>Pass@1=67.6</code>，高于 DeepSeek-V3.1 <code>49.6</code>；<code>Pass@32=81.6</code>。</li><li>Lean4 迭代证明数据形成了突出的专门能力。</li></ul><p><strong>Agent 与通用任务</strong></p><ul><li>SWE-bench <code>59.4</code>、τ₂ Avg <code>74.0</code>、VitaBench <code>29.5</code>；不同 Agent 场景仍有明显差异。</li><li>MMLU-Pro <code>82.6</code>、IFEval <code>86.9</code>，领域推理优势没有覆盖所有通用任务。</li></ul><p><strong>系统效率</strong></p><ul><li>图编译带来约 <code>1.5倍</code> rollout 加速；完整 DORA 系统相比同步训练超过 <code>3倍</code>。</li><li>系统收益来自减少长尾等待与角色空闲，为扩大 RL 计算投入提供条件。</li></ul></div><h3 id="未来方向-1" tabindex="-1">未来方向 <a class="header-anchor" href="#未来方向-1" aria-label="Permalink to &quot;未来方向&quot;">​</a></h3><div class="custom-block info"><div class="custom-block-title">后续研究(笔记归纳)</div><p><strong>能力融合</strong></p><ul><li>分析哪些领域最容易在融合后退化，联合调整任务增量、数据配比与最后的通用 RL。</li><li>将工具必要性筛选扩展到真实搜索、代码维护和多轮业务任务。</li></ul><p><strong>异步稳定性</strong></p><ul><li>联合控制 replay 比例、策略 staleness 与概率修正，提高旧样本利用率。</li><li>在相同总计算预算下比较工具推理与更长 CoT，明确延迟、成本和成功率的取舍。</li></ul></div><h2 id="_2509-longcat-flash-零计算专家、scmoe、动态计算" tabindex="-1">(2509) LongCat-Flash (零计算专家、ScMoE、动态计算) <a class="header-anchor" href="#_2509-longcat-flash-零计算专家、scmoe、动态计算" aria-label="Permalink to &quot;(2509) LongCat-Flash (零计算专家、ScMoE、动态计算)&quot;">​</a></h2><p><strong>🌺 论文摘要</strong></p><div class="custom-block danger"><div class="custom-block-title">LongCat-Flash 摘要</div><p><strong>参考链接</strong></p><ul><li><a href="https://www.alphaxiv.org/abs/2509.01322" target="_blank" rel="noreferrer">paper</a>，<a href="https://huggingface.co/meituan-longcat/LongCat-Flash-Chat" target="_blank" rel="noreferrer">官方模型</a>。</li></ul><p><strong>问题背景</strong></p><ul><li>不同 token 难度不同，固定激活专家数浪费计算；大规模 MoE 的通信又限制实际吞吐。</li><li>基模扩展需要同时解决初始化、路由稳定、数据配比及真实 Agent 任务供给。</li></ul><p><strong>核心方法</strong></p><ul><li><strong>动态架构</strong>：零计算专家与普通 FFN 共同参与路由，平均激活 <code>27B</code>；ScMoE 扩大计算通信重叠。</li><li><strong>预训练与扩展</strong>：约 <code>20T</code> 预训练 → 推理/代码 MidTrain → <code>128K</code> 扩窗；超参迁移与路由稳定化支持模型增长。</li><li><strong>后训练数据</strong>：覆盖推理、SWE、工具、长文和安全；按工具依赖、信息处理与交互复杂度合成 Agent 任务。</li><li><strong>训练与部署系统</strong>：确定性训练与故障检测控制恢复成本，配合 SBO、MTP 和调度优化吞吐。</li></ul><p><strong>模型效果(LongCat-Flash-Chat，非 Thinking)</strong></p><ul><li>SWE-bench Verified <code>60.4</code>、TerminalBench <code>39.5</code>、IFEval <code>89.7</code>；VitaBench <code>24.3</code>。</li><li><code>128×H800</code>、约 <code>5K</code> 上下文的低延迟配置，每用户约 <code>100 tokens/s</code>。</li></ul><p><strong>重要结论</strong></p><ul><li>匹配平均计算量的消融中，动态专家降低验证 loss；并非仅通过增加计算获得收益。</li><li>ScMoE 在多种模型规模和注意力结构中保持相近 loss，主要收益来自通信与计算重叠。</li></ul><p><strong>核心贡献</strong></p><ul><li>将动态 MoE 计算、稳定训练和低延迟部署结合，并开放具有 Agent 能力的基座与 Chat 模型。</li></ul><p><strong>未来方向</strong></p><ul><li><strong>笔记归纳</strong>：优化动态路由与服务负载协同，补强长上下文推理和基础代码生成。</li></ul></div><h3 id="问题背景-2" tabindex="-1">问题背景 <a class="header-anchor" href="#问题背景-2" aria-label="Permalink to &quot;问题背景&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">MoE 的计算与扩展效率</div><p><strong>计算分配固定</strong></p><ul><li>易预测 token 和关键推理 token 都使用相同专家预算，难以按上下文分配算力。</li></ul><p><strong>稀疏但仍受通信限制</strong></p><ul><li>token 必须先分发到专家再计算，dispatch/combine 形成串行等待。</li><li>模型变大后，低秩注意力、细粒度专家和路由器的数值尺度也更容易失衡。</li></ul></div><h3 id="核心方法-2" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法-2" aria-label="Permalink to &quot;核心方法&quot;">​</a></h3><h4 id="动态-moe-架构" tabindex="-1">动态 MoE 架构 <a class="header-anchor" href="#动态-moe-架构" aria-label="Permalink to &quot;动态 MoE 架构&quot;">​</a></h4><div class="custom-block important"><div class="custom-block-title">Zero-Computation Experts</div><p><strong>专家池</strong></p><ul><li>每层 <code>512个 FFN专家 + 256个零计算专家</code>，共同选取 <code>Top-12</code>。</li><li>零计算专家输出输入本身 <code>E(x)=x</code>，不是零向量，也不执行 FFN。</li><li>Top-k 数量固定，选中的实际 FFN 数量随 token 变化。</li></ul><p><strong>平均预算控制</strong></p><ul><li>依据近期使用量调整 FFN 专家的路由 bias，使平均激活约 <code>8个真实专家</code>。</li><li>零计算专家不单独更新 bias；FFN 使用率达到目标时，剩余份额自然分给恒等专家。</li><li>再加入设备级负载平衡，避免某些 EP 设备收到过多 token。</li></ul></div><div class="custom-block note"><div class="custom-block-title">Shortcut-Connected MoE</div><p><strong>结构</strong></p><ul><li>每个模型 block 包含两组 MLA 及 Dense FFN，并通过跨层 shortcut 连接 MoE。</li><li>前一块 Dense FFN 的计算可与当前 MoE 的分发、聚合通信并行。</li></ul><p><strong>执行</strong></p><ul><li>训练时再按 token 切块，扩大不同 chunk 之间的重叠。</li><li>推理采用 Single Batch Overlap，不必依赖两个 batch 交错才能隐藏通信。</li><li>节省的是设备等待时间，与零计算专家减少实际 FFN 计算互补。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">MLA 方差校正与专家初始化</div><p><strong>MLA</strong></p><ul><li>Query、KV 低秩路径与 RoPE 路径来源维度不同，初始化方差容易不一致。</li><li>按模型维度与压缩维度的平方根比缩放低秩路径，使注意力各分量处于可比较尺度。</li></ul><p><strong>细粒度专家</strong></p><ul><li>专家拆得更细时，gate 权重与中间维度同时缩小，聚合输出方差也下降。</li><li>按拆分系数补偿聚合输出，减少专家数量变化对初始化尺度的影响。</li></ul></div><h4 id="预训练与稳定扩展" tabindex="-1">预训练与稳定扩展 <a class="header-anchor" href="#预训练与稳定扩展" aria-label="Permalink to &quot;预训练与稳定扩展&quot;">​</a></h4><div class="custom-block note"><div class="custom-block-title">超参迁移与 Model Growth</div><p><strong>宽度迁移</strong></p><ul><li>在宽度 <code>768</code> 的 proxy 搜索初始化与学习率，再按 <code>s=8</code> 迁移至 <code>6144</code>。</li><li>Embedding 保持学习率与初始化方差；Hidden / Unembedding 的两者按 <code>1/s</code> 缩放。</li><li>迁移时保持深度、稀疏度和 batch 等其他结构条件一致。</li></ul><p><strong>模型增长</strong></p><ul><li>先训练 <code>14层</code>同构模型，再整体堆叠两份成为 <code>28层</code>。</li><li>保留样本计数和学习率日程，继续训练；增长时机避免前驱模型过度优化。</li></ul></div><div class="custom-block important"><div class="custom-block-title">Router、激活与优化器稳定性</div><p><strong>Router 平衡</strong></p><ul><li>LM loss 推动专家分工，负载平衡 loss 推动均匀分配；后者过强会使路由失去输入差异。</li><li>监测专家权重相似度与两类梯度范数比，控制负载平衡梯度不压过 LM 梯度。</li></ul><p><strong>Hidden z-loss</strong></p><ul><li>对最终 LayerNorm 前的极大 hidden 激活施加很小惩罚，降低 BF16 数值不稳定风险。</li></ul><p><strong>Adam ε</strong></p><ul><li>大模型、大 batch 下梯度尺度变小，ε 过大会干扰自适应更新。</li><li>使用 <code>ε=1e-16</code>，使其远小于观测到的梯度 RMS。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">数据配比与长上下文扩展</div><p><strong>通用预训练</strong></p><ul><li>网页提取、分类器粗筛、流畅性/完整性细筛、MinHash 去重，并清理模板重复。</li><li>第一阶段按质量与多样性采样；第二阶段逐步提高 STEM + Code 至约 <code>70%</code>。</li><li>监控通用验证集 PPL，避免突然降低通用语料比例导致能力退化。</li></ul><p><strong>推理与代码 MidTrain</strong></p><ul><li>从知识图谱遍历、组合概念生成复杂问题，迭代增加难度与 CoT 质量。</li><li>联合文本推理和代码执行验证，构建高质量合成数据，并复用筛选后的预训练材料。</li></ul><p><strong>长上下文</strong></p><ul><li><code>80B tokens</code> 将 <code>8K→32K</code>，再以 <code>20B tokens</code> 扩至 <code>128K</code>。</li><li>加入书籍和按仓库组织的代码，保留跨文件关系；长文本数据约占混合中的 <code>25%</code>。</li><li>Web / Code 做 13-gram 去污染，合成 QA 再以语义相似度排除测试重叠。</li></ul></div><h4 id="多领域后训练数据" tabindex="-1">多领域后训练数据 <a class="header-anchor" href="#多领域后训练数据" aria-label="Permalink to &quot;多领域后训练数据&quot;">​</a></h4><div class="custom-block note"><div class="custom-block-title">Reasoning 与 SWE</div><p><strong>数学与逻辑</strong></p><ul><li>用不同数学专家 persona 生成问题，多模型答案一致性与推理 GenRM 联合验证。</li><li>逻辑题控制难度，去掉强推理模型也无法解决的题，将选择题转为填空以减少猜测。</li></ul><p><strong>代码与仓库任务</strong></p><ul><li>公共题、GitHub 片段、论坛与 Evol-Instruct 扩展题库，按主题和难度平衡。</li><li>筛除题意不清、重复、乱码和错误响应。</li><li>构建上万个含测试的 Docker 环境，Agent 搜索、定位、修复，保留数千条全测试通过轨迹。</li></ul></div><div class="custom-block important"><div class="custom-block-title">Agentic Tool-Use 合成</div><p><strong>难度控制</strong></p><ul><li><strong>信息处理</strong>：约束数量、推理节点和依赖链长度。</li><li><strong>工具集</strong>：工具依赖图的节点数量、连接密度。</li><li><strong>用户交互</strong>：表达风格、配合程度、信息披露方式，要求少打扰但获取必要信息。</li></ul><p><strong>任务生成</strong></p><ul><li>UserProfileAgent 定义用户状态；ToolSetAgent 构建 <code>40领域 / 1600应用 / 80K模拟工具</code>。</li><li>从工具图随机游走采样子图，InstructionAgent 生成满足复杂度要求的任务。</li><li>EnvironmentAgent 补充商品、地点、时间等状态，并加入容易混淆的选项。</li><li>RubricAgent 生成验收清单；Validator / Deduplicator 检查可评估性与任务重复。</li></ul><p><strong>轨迹验收</strong></p><ul><li>滑动窗口检查长轨迹，持续更新清单完成状态。</li><li>冷启动保留多样解法，后续任务选择强调值得持续探索的难度。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">指令、长文与安全</div><p><strong>指令与长文</strong></p><ul><li>多约束任务先检查冲突；对难以直接合成的约束，由合格答案反向生成问题。</li><li>长文包括阅读、表格问答和自定义任务，组合相关片段训练多跳推理与跨轮信息利用。</li></ul><p><strong>安全与知识不足</strong></p><ul><li>数据区分不同风险类别与响应方式，经人工复核再作为训练目标。</li><li>上下文不完整时训练适当说明信息不足，减少缺少证据仍给出确定回答。</li></ul></div><h4 id="训练系统与推理部署" tabindex="-1">训练系统与推理部署 <a class="header-anchor" href="#训练系统与推理部署" aria-label="Permalink to &quot;训练系统与推理部署&quot;">​</a></h4><div class="custom-block note"><div class="custom-block-title">确定性训练与故障检测</div><p><strong>算子与 SDC</strong></p><ul><li>对照高精度参考检查算子误差；重算敏感算子，以 bitwise 差异检测 Silent Data Corruption。</li><li>固定 Attention backward、ScatterAdd 等归约顺序，保证相同训练步骤可重现。</li></ul><p><strong>并行与恢复</strong></p><ul><li><code>EP=32、CP=8</code>，结合 PP / DP 与 V-ZB 流水线，降低通信和显存峰值。</li><li>异步 checkpoint、自动日志检测与故障恢复，减少大集群训练中断。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">SBO、MTP 与调度</div><p><strong>模型侧</strong></p><ul><li>SBO 将 dispatch 与 Dense / QKV 计算重叠，combine 与 attention / Dense 重叠。</li><li>轻量单 Dense MTP 层提出候选，主模型验证；MLA 压缩 KV Cache。</li></ul><p><strong>系统侧</strong></p><ul><li>Target、Verification、Draft 合入一张 CUDA Graph，减少多阶段 kernel 启动。</li><li>多步重叠调度隐藏 CPU 开销；PD 分离并逐层传输 KV，分别优化输入处理和生成。</li><li>FP8 分块量化，按层保留敏感部分的更高精度；零计算专家无需远程 FFN 通信。</li></ul></div><h3 id="实验设置-longcat-flash" tabindex="-1">实验设置(LongCat-Flash) <a class="header-anchor" href="#实验设置-longcat-flash" aria-label="Permalink to &quot;实验设置(LongCat-Flash)&quot;">​</a></h3><div class="custom-block tip"><div class="custom-block-title">模型、训练与评测</div><p><strong>模型配置</strong></p><ul><li><code>560B</code>，平均激活 <code>27B</code>；<code>28 blocks、hidden=6144、词表=131072</code>。</li><li>MLA：<code>64 heads、KV压缩512、Query压缩1536</code>；<code>512 FFN + 256零计算专家 / Top-12</code>。</li></ul><p><strong>训练阶段</strong></p><ul><li>通用预训练约 <code>20T tokens / seq_len=8K</code>，随后推理代码增强与长上下文扩展。</li><li>后训练覆盖 reasoning、coding、tool-use 和 general；报告主要展开数据构建，未完整给出优化配方。</li></ul><p><strong>对照设计</strong></p><ul><li>动态专家消融匹配平均 FFN 计算量；ScMoE 在 MLA、MHA、GQA 和不同规模下比较。</li><li>分别评估 Base 与非 Thinking Chat，覆盖知识、推理、代码、SWE、工具和指令任务。</li><li>部署测试使用 H800，报告不同吞吐/延迟配置；不能合并为同一运行点。</li></ul></div><h3 id="关键结果-longcat-flash-预训练-多领域后训练" tabindex="-1">关键结果(LongCat-Flash，预训练 + 多领域后训练) <a class="header-anchor" href="#关键结果-longcat-flash-预训练-多领域后训练" aria-label="Permalink to &quot;关键结果(LongCat-Flash，预训练 + 多领域后训练)&quot;">​</a></h3><div class="custom-block important"><div class="custom-block-title">结构与稳定性消融</div><p><strong>动态计算</strong></p><ul><li>匹配平均 <code>8个 FFN专家</code>时，加入零计算专家的验证 loss 更低。</li><li>实际激活量随 token 明显变化，平均预算仍稳定，支持按上下文分配计算。</li></ul><p><strong>通信重叠</strong></p><ul><li>多组 ScMoE 消融的 loss 接近基线；训练中未被隐藏的通信占比 <code>25.3% → 8.4%</code>。</li><li>性能收益主要来自执行效率，结构调整没有显示明显质量损失。</li></ul><p><strong>训练稳定</strong></p><ul><li>MLA 尺度校正改善收敛；Model Growth 优于随机初始化；hidden z-loss 压低异常激活。</li><li>大规模训练约 <code>30天</code>完成，时间可用率 <code>98.48%</code>，减少故障造成的计算浪费。</li></ul></div><figure style="margin:24px 0;"><img src="https://arxiv.org/html/2509.01322v2/valid_loss_enbook.svg" alt="相同平均计算预算下的消融：零计算专家版本的验证 loss 更低；这里比较的是动态计算分配，不是单纯增加激活参数。" loading="lazy" style="display:block;margin:12px auto;background:#fff;" width="100%"><figcaption style="font-size:0.9em;line-height:1.6;color:var(--vp-c-text-2);"><strong>原文图 3(a)：</strong>相同平均计算预算下的消融：零计算专家版本的验证 loss 更低；这里比较的是动态计算分配，不是单纯增加激活参数。 <a href="https://arxiv.org/html/2509.01322v2#S2.F3" target="_blank" rel="noreferrer">来源</a></figcaption></figure><div class="custom-block tip"><div class="custom-block-title">模型能力与部署表现</div><p><strong>Base 与 Chat</strong></p><ul><li>Base MMLU-Pro <code>70.3</code>、GPQA <code>51.1</code>，展现较好的激活参数效率。</li><li>Chat IFEval <code>89.7</code>、COLLIE <code>57.1</code>、Meeseeks-zh <code>43.0</code>，指令与多轮交互是较强项。</li></ul><p><strong>代码与 Agent</strong></p><ul><li>SWE-bench Verified <code>60.4</code>、TerminalBench <code>39.5</code>；后者接近 Claude 4 Sonnet <code>40.7</code>。</li><li>VitaBench <code>24.3</code>，高于表中 Sonnet <code>23.0</code>；工具交互形成较突出能力。</li><li>HumanEval+ <code>88.4</code>，低于 Qwen3 <code>94.5</code>；GraphWalks-128K <code>51.1</code>，长文复杂推理仍较弱。</li></ul><p><strong>推理效率</strong></p><ul><li><code>128×H800、平均5K上下文</code>：低延迟配置 <code>100.5 tokens/s/用户</code>，对应 <code>804 tokens/s/GPU</code>。</li><li>同硬件的高吞吐配置可达 <code>3785 tokens/s/GPU</code>，但每用户速度为 <code>35 tokens/s</code>。</li><li>服务部署需要按交互延迟和批量吞吐目标选择运行点。</li></ul></div><h3 id="未来方向-2" tabindex="-1">未来方向 <a class="header-anchor" href="#未来方向-2" aria-label="Permalink to &quot;未来方向&quot;">​</a></h3><div class="custom-block info"><div class="custom-block-title">后续研究</div><p><strong>作者指出的系统问题</strong></p><ul><li>算子数值误差与最终能力的关系仍难低成本评估，需要更有效的精度评测方法。</li></ul><p><strong>笔记归纳</strong></p><ul><li>让动态专家预算与实际服务负载协同，避免平均算力受控但局部设备仍拥堵。</li><li>加强基础代码生成、长上下文多跳推理，缩小不同任务之间的能力差距。</li><li>在真实工具延迟下优化完整 Agent 耗时，区分模型生成加速和任务完成加速。</li></ul></div>',89)]))}const h=o(s,[["render",n]]);export{p as __pageData,h as default};
